using System.Linq;using UnityEngine;using UnityEditor;
public static class AuditCemetery {public static string Run(){AssetDatabase.Refresh();return string.Join("\n",AssetDatabase.FindAssets("t:Model",new[]{"Assets/03_Models/Cemetery","Assets/Necromanser"}).Select(g=>{var p=AssetDatabase.GUIDToAssetPath(g);var go=AssetDatabase.LoadAssetAtPath<GameObject>(p);return p+" skins="+go.GetComponentsInChildren<SkinnedMeshRenderer>().Length+" clips="+string.Join(",",AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__")).Select(c=>c.name+":"+c.length))+" materials="+string.Join(",",go.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.name).Distinct());}));}}
